// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }
    function testRegression_property() public {
        Token token = new Token();
        address tokenAddr = address(token);
        address from = address(0x123);
        address to = address(0x456);

        vm.deal(from, 1 ether);

        c.transfer(from, tokenAddr, _toSingleton(to), 10, 1);

        uint256 bal = token.balanceOf(to);
        assertTrue(bal == 100, "Balance should be 100");
    }

    function _toSingleton(address a) private pure returns (address[] memory) {
        address[] memory arr = new address[](1);
        arr[0] = a;
        return arr;
    }
}

contract Token {
    mapping(address => uint256) public balanceOf;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        balanceOf[to] += value;
        return true;
    }
}
